{
  "kb_type": "test_pattern",
  "id": "common-tp-happy-get-single",
  "category": "Happy Path",
  "methods": [
    "GET"
  ],
  "title": "Fetch a single resource by valid ID",
  "description": "Call the endpoint with a valid path parameter identifying an existing resource. Expect 200 and a response body matching the documented schema."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-happy-list-filtered",
  "category": "Happy Path",
  "methods": [
    "GET"
  ],
  "title": "List resources with valid filter/query parameters",
  "description": "Call a collection endpoint with valid, documented query parameters (filters, sort, pagination). Expect 200 and results consistent with the applied filters."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-happy-create",
  "category": "Happy Path",
  "methods": [
    "POST"
  ],
  "title": "Create resource with valid payload",
  "description": "Send a fully valid request body containing all required fields. Expect the documented success status (200/201) and a response body reflecting the created resource, including a generated identifier."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-happy-update-full",
  "category": "Happy Path",
  "methods": [
    "PUT"
  ],
  "title": "Full update replaces resource",
  "description": "Send a complete valid representation of the resource. Expect 200/204 and the resource fully replaced with the new values on subsequent GET."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-happy-update-partial",
  "category": "Happy Path",
  "methods": [
    "PATCH"
  ],
  "title": "Partial update changes only targeted fields",
  "description": "Send a partial payload with a subset of fields. Expect 200 and confirm unrelated fields remain unchanged."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-happy-delete",
  "category": "Happy Path",
  "methods": [
    "DELETE"
  ],
  "title": "Delete an existing resource",
  "description": "Delete a resource that exists. Expect 200/204 and confirm a subsequent GET on the same resource returns 404."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-neg-duplicate-unique",
  "category": "Negative",
  "methods": [
    "POST"
  ],
  "title": "Duplicate unique field rejected",
  "description": "Attempt to create a resource with a value that must be unique (e.g. email, username) that already exists. Expect 409 Conflict or 400 with a clear error message."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-boundary-pagination",
  "category": "Boundary",
  "methods": [
    "GET"
  ],
  "title": "Pagination parameter boundary values",
  "description": "Test page=0, page=-1, limit=0, and an extremely large limit/offset. Expect the API to clamp or reject rather than error or return unbounded results."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-schema-nullable",
  "category": "Schema",
  "methods": [
    "GET"
  ],
  "title": "Nullable fields returned explicitly as null",
  "description": "For fields marked nullable, verify the API returns an explicit null value rather than omitting the key when no value is set."
}

{
  "kb_type": "test_pattern",
  "id": "common-tp-edge-idempotency",
  "category": "Edge",
  "methods": [
    "POST"
  ],
  "title": "Idempotency key prevents duplicate creation",
  "description": "Send the identical request twice with the same idempotency key. Expect the second response to return the original resource rather than creating a duplicate."
}

{
  "kb_type": "boundary_value",
  "type_name": "enum",
  "description": "Boundary cases for enum fields",
  "cases": [
    "first_value",
    "last_value",
    "value_not_in_enum"
  ]
}

